import hmac
import os
import unittest


def constant_time_compare(a, b):
    """Constant-time comparison of two byte or string values."""
    if not isinstance(a, bytes):
        a = a.encode("utf-8")
    if not isinstance(b, bytes):
        b = b.encode("utf-8")
    return hmac.compare_digest(a, b)


def hash_password(password, salt=None, iterations=200_000, hash_name="sha256"):
    """Hash a password with PBKDF2-HMAC and a random salt."""
    if isinstance(password, str):
        password = password.encode("utf-8")
    if salt is None:
        salt = os.urandom(16)
    elif isinstance(salt, str):
        salt = bytes.fromhex(salt)

    derived = hashlib.pbkdf2_hmac(hash_name, password, salt, iterations)
    return f"{hash_name}${iterations}${salt.hex()}${derived.hex()}"


def verify_password(password, password_hash):
    """Verify a password against a PBKDF2 hash string."""
    if isinstance(password, str):
        password = password.encode("utf-8")

    try:
        hash_name, iterations_str, salt_hex, expected_hex = password_hash.split("$")
        iterations = int(iterations_str)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(expected_hex)
    except (ValueError, TypeError):
        return False

    derived = hashlib.pbkdf2_hmac(hash_name, password, salt, iterations)
    return constant_time_compare(derived, expected)


class TestSecurePassword(unittest.TestCase):
    def test_hash_and_verify(self):
        for password in ["secret", "Ünîcôdé", ""]:
            hashed = hash_password(password)
            self.assertTrue(verify_password(password, hashed))
            self.assertFalse(verify_password(password + "x", hashed))

    def test_custom_salt_and_iterations(self):
        salt = os.urandom(16)
        hashed = hash_password("password", salt=salt, iterations=50_000)
        self.assertTrue(verify_password("password", hashed))
        self.assertIn(salt.hex(), hashed)

    def test_constant_time_compare(self):
        self.assertTrue(constant_time_compare("abc", "abc"))
        self.assertFalse(constant_time_compare("abc", "abd"))
        self.assertFalse(constant_time_compare("abc", "abcd"))

    def test_invalid_hash_rejected(self):
        self.assertFalse(verify_password("password", "bad"))
        self.assertFalse(verify_password("password", "sha256$X$salt$hash"))


if __name__ == "__main__":
    unittest.main()
